// Editorial migration input. Each option has its own scenario-specific rationale.
// These are authored revisions, not a runtime question generator.
export const edits = {};
function add(id, question, options, reasons, sources) {
  edits[id] = { question, options, reasons, sources };
}
const responsible = ['responsible', 'tests'];
function many(ids, options, reasons, sources) {
  for (const id of ids.split(' ')) add(id, null, options, reasons, sources);
}
